#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/kotlin/tasks/setup-deps-kotlin.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Resolve the Gradle dependencies and check that the lockfiles cover them; --upgrade writes new lockfiles"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}
# USAGE flag "--upgrade" help="refresh the dependencies, write new lockfiles and report the outdated ones"

import hashlib
import os
import re
import shutil
import signal
import subprocess
import sys
import tempfile

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402

SPACE = rb"[ \t\r\f\v]"
CHECKSUM = re.compile(
  SPACE + rb"*distributionSha256Sum" + SPACE + rb"*[=:]" + SPACE + rb"*[0-9a-fA-F]{64}" + SPACE + rb"*"
)
STRICT = "org.gradle.api.artifacts.dsl.LockMode.STRICT"


def exit_code(code):
  """The exit code of the shell for a return code of subprocess."""
  return code if code >= 0 else 128 - code


def on_signal(signum, frame):
  """An interrupt stops the task with code 130, and the cleanup runs."""
  sys.exit(130)


def has_checksum(path):
  """Whether a line of the file path sets distributionSha256Sum to a SHA-256,
  64 hex digits. A present key is not enough."""
  try:
    with open(path, "rb") as data:
      lines = data.read().split(b"\n")
  except OSError:
    return False
  return any(CHECKSUM.fullmatch(line) for line in lines)


def lockfiles(folder="."):
  """The lockfiles on the disk below the root. Gradle writes gradle.lockfile,
  settings-gradle.lockfile and buildscript-gradle.lockfile; the pattern
  matches all of them in any folder. The search does not use git, so the
  result is correct in a root that is not a git repository and for ignored
  lockfiles. It does not go into hidden folders (.git, .gradle, worktrees),
  build outputs or node_modules. It also does not go into a folder below the
  root with .git or settings.gradle(.kts): a git submodule or a nested Gradle
  build, which the resolve does not cover. It does not follow a symlink.
  """
  found = []
  try:
    entries = list(os.scandir(folder))
  except OSError:
    return found
  for entry in entries:
    if entry.is_dir(follow_symlinks=False):
      name = entry.name
      if (name.startswith(".") and len(name) > 1) or name in ("build", "node_modules"):
        continue
      if any(os.path.exists(f"{entry.path}/{marker}") for marker in (".git", "settings.gradle.kts", "settings.gradle")):
        continue
      found.extend(lockfiles(entry.path))
    elif entry.is_file(follow_symlinks=False) and entry.name.endswith("gradle.lockfile"):
      found.append(entry.path)
  return found


def lock_state():
  """A checksum for each lockfile, in a fixed order. Two snapshots are equal
  only when no lockfile was added, removed or changed. It does not use git."""
  state = []
  for file in sorted(lockfiles(), key=os.fsencode):
    try:
      with open(file, "rb") as data:
        state.append((file, hashlib.sha256(data.read()).hexdigest()))
    except OSError:
      state.append((file, None))
  return state


def init_script(upgrade):
  """The init script of bootstrapResolveAll.

  Every resolvable configuration of every project, not the root's alone. The
  legacy default and archives configurations are for other projects, so the
  task does not resolve them. A configuration from configurations.create() is
  also consumable (detekt, ktlint, a custom tool), and the task resolves it,
  so its lock is examined and written. The list is a copy, so a resolve that
  adds a configuration does not change the loop. A normal run sets
  LockMode.STRICT on the settings buildscript classpath before the settings
  script, and on each project and on its buildscript classpath when Gradle
  creates the project, before its build script: a resolve fails on a mismatch
  with a lockfile, and on a locked configuration with no lock state.
  --upgrade does not set STRICT, so a new module gets its first lockfile
  there. bootstrapResolveAll and dependencyUpdates cannot use the
  configuration cache, so each ./gradlew call turns it off, and Gradle prints
  no cache warnings.
  """
  lines = []
  if not upgrade:
    lines.append(f"beforeSettings {{ s -> s.buildscript.dependencyLocking.lockMode.set({STRICT}) }}")
  lines.append("allprojects { p ->")
  if not upgrade:
    lines.append(f"  p.dependencyLocking.lockMode.set({STRICT})")
    lines.append(f"  p.buildscript.dependencyLocking.lockMode.set({STRICT})")
  lines += [
    '  p.tasks.register("bootstrapResolveAll") {',
    '    notCompatibleWithConfigurationCache("resolves the configurations at execution time")',
    "    def confs = p.configurations",
    (
      '    doLast { confs.matching { it.canBeResolved && !(it.name in ["default", "archives"]) }.toList().each {'
      " it.resolve() } }"
    ),
    "  }",
    "}",
  ]
  return "".join(f"{line}\n" for line in lines)


def tee(args, log):
  """Run args with stdout and stderr on stdout and in the file log, and return
  the exit code of args."""
  with open(log, "wb") as out:
    with subprocess.Popen(args, stdout=subprocess.PIPE, stderr=subprocess.STDOUT) as process:
      for chunk in iter(lambda: process.stdout.read1(65536), b""):
        sys.stdout.buffer.write(chunk)
        sys.stdout.buffer.flush()
        out.write(chunk)
    return process.returncode


def main():
  # Shipped with the kotlin tool. Without an executable ./gradlew at the root,
  # there is no Gradle build here, so the task does not apply and prints
  # nothing. The android/ build of a Flutter app belongs to
  # setup:deps:20-flutter.
  root = os.environ["MISE_PROJECT_ROOT"]
  if not os.access(f"{root}/gradlew", os.X_OK):
    sys.exit(0)

  os.chdir(root)
  upgrade = os.environ.get("usage_upgrade", "false") == "true"

  if upgrade:
    helpers.print_header("Upgrading the Gradle dependencies ...")
  else:
    helpers.print_header("Installing the Gradle dependencies ...")

  # Only the distribution is checked; the wrapper downloads it before any
  # build.
  helpers.print_subheader("Checking the Gradle distribution checksum ...")
  if not has_checksum("gradle/wrapper/gradle-wrapper.properties"):
    helpers.print_error("gradle/wrapper/gradle-wrapper.properties sets no valid distributionSha256Sum.")
    helpers.print_info("Set it to the 64-hex checksum that Gradle publishes for the distribution, then re-run.")
    sys.exit(1)
  helpers.print_success("distributionSha256Sum is set.")

  # The temporary folder holds the init script and the dependencyUpdates log.
  tmp_dir = tempfile.mkdtemp(prefix="bootstrap-gradle.", dir=os.environ.get("TMPDIR") or "/tmp")
  signal.signal(signal.SIGINT, on_signal)
  signal.signal(signal.SIGTERM, on_signal)
  try:
    script = f"{tmp_dir}/resolve-all.gradle"
    with open(script, "w", encoding="utf-8") as out:
      out.write(init_script(upgrade))

    if upgrade:
      helpers.print_subheader("Writing new lockfiles for every project ...")
      before = lock_state()
      result = subprocess.run(
        [
          "./gradlew",
          "--no-configuration-cache",
          "--init-script",
          script,
          "bootstrapResolveAll",
          "--write-locks",
          "--refresh-dependencies",
        ],
        check=False,
      )
      if result.returncode != 0:
        sys.exit(exit_code(result.returncode))

      # Gradle writes a lockfile only for a project with dependencyLocking.
      # The last message tells whether the resolve changed a lockfile, from
      # the two checksum snapshots, so it is correct without git and for
      # ignored lockfiles.
      after = lock_state()

      def upgrade_done():
        if not after:
          helpers.print_warn("No project has dependencyLocking, so the resolve wrote no lockfile.")
        elif after != before:
          helpers.print_success("Commit the new lockfiles.")
        else:
          helpers.print_success("The lockfiles did not change.")

      # dependencyUpdates comes from the ben-manes versions plugin. Only
      # Gradle's task-not-found error is a skip; any other failure is the
      # build's.
      helpers.print_subheader("Checking for outdated Gradle dependencies ...")
      log = f"{tmp_dir}/outdated.log"
      if tee(["./gradlew", "--no-configuration-cache", "dependencyUpdates"], log) == 0:
        upgrade_done()
        sys.exit(0)
      with open(log, "rb") as data:
        output = data.read()
      if re.search(rb"Task '(:)?dependencyUpdates' not found", output):
        helpers.print_info(
          "No dependencyUpdates task (the ben-manes plugin com.github.ben-manes.versions), so no report."
        )
        upgrade_done()
        sys.exit(0)
      helpers.print_error("./gradlew dependencyUpdates failed; its output is above.")
      sys.exit(1)

    # A normal run resolves against the lockfiles on the disk and writes no
    # file. Gradle pins each locked version, so a dynamic version stays at its
    # locked version. A module without dependencyLocking has no lock state and
    # is not checked. A failure can also come from the network or the build,
    # so the advice to run --upgrade applies only when Gradle names the lock
    # state.
    helpers.print_subheader("Resolving every project against its lockfile ...")
    result = subprocess.run(
      ["./gradlew", "--no-configuration-cache", "--init-script", script, "bootstrapResolveAll"], check=False
    )
    if result.returncode != 0:
      helpers.print_error("./gradlew failed; its output is above.")
      helpers.print_info(
        "If the output names the dependency lock state, run 'mise run setup:deps:30-kotlin --upgrade', then commit"
        " the lockfiles."
      )
      sys.exit(1)

    if not lockfiles():
      helpers.print_warn("No project has dependencyLocking, so there is no lockfile to check.")
      sys.exit(0)
    helpers.print_success("The lockfiles cover each resolvable configuration of each project with dependencyLocking.")
  finally:
    shutil.rmtree(tmp_dir, ignore_errors=True)


main()
